<script setup>
import ProductImage from "../components/ProductImage.vue";
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {products,money} from '../data/catalog';import {useCart} from '../composables/cart';const route=useRoute(),{add,open,lines}=useCart();const p=products.find(p=>p.id===route.params.id&&p.seller===route.params.seller);const variant=ref(p?.variants.find(v=>v.stock>0)?.id||p?.variants[0]?.id||null),qty=ref(1);const v=computed(()=>p?.variants.find(v=>v.id===variant.value));const remaining=computed(()=>Math.max(0,(v.value?.stock??p?.stock??0)-(lines.value.find(l=>l.id===p?.id&&l.variant===(v.value?.id||null))?.qty||0)));function buy(){if(add(p,v.value,qty.value))open.value=true}
</script>
<template><div class="shell py-8"><router-link :to="'/store/'+route.params.seller" class="secondary mb-6"><i class="fa-solid fa-arrow-left"></i> Back to store</router-link><div v-if="p" class="grid gap-8 md:grid-cols-2" data-aos="fade-up"><div class="art group overflow-hidden !text-[140px]"><ProductImage :src="p.image" :alt="p.name" :emoji="p.emoji" eager/></div><div class="panel"><p class="text-sm text-green-700">{{p.category}}</p><h1 class="my-3 text-4xl font-black">{{p.name}}</h1><p class="text-3xl font-bold text-[#00532d]">{{money(v?.price??p.price)}}</p><p class="my-5 text-gray-600">{{p.description}}</p><div v-if="p.variants.length"><p class="mb-2 font-bold">Choose an option</p><button v-for="o in p.variants" :key="o.id" :class="variant===o.id?'primary':'secondary'" class="mr-2 mb-2" :disabled="!o.stock" @click="variant=o.id;qty=1">{{o.name}}</button></div><p class="my-4 text-sm">{{remaining}} available to add</p><div class="stepper"><button :disabled="qty<=1" @click="qty--" aria-label="Decrease">−</button>{{qty}}<button :disabled="qty>=remaining" @click="qty++" aria-label="Increase">+</button></div><button class="primary mt-6 w-full" :disabled="qty>remaining" @click="buy">Add to basket · {{money((v?.price??p.price)*qty)}}</button></div></div><div v-else class="panel">Product not found.</div></div></template>
